-- One ask_aar_snapshots row for ASK 651 (the PROVEN IN check reads a quotation to the end of its line) and its ask_aar_builders row.
-- Every value is from Wall 12100, 12101, 12102, 12105, 12108, 12127, 12129, 12139, 12145 and 12152, ask651/w4/plan651.md rev 0 (read whole) (each read whole by W3), W4's facts file aar/w3/cards_641_to_652_from_w4.md (md5 380e6b134460a413f6f57ea766452fc7), and md5sum by W3 of the files named.
-- NOT READ by W3: the card and the press in W4's thread (taken from W4's facts file); the audit_log row; the live engine and n8n; W1's grade files in git.
-- objective_met is 'in part': written and read back; no run since the write.
-- After the insert: SELECT * FROM ask_aar_snapshots_check(); SELECT * FROM ask_aar_grades_check();
-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (651, '0', $t$ASK 651: the PROVEN IN check reads a quotation to the end of its line, not 160 characters$t$,
  $t$PRS refCheck tests whether a PROVEN IN round quotes the verse with its reference. It read only 160 characters after the reference, so when the closing quotation mark fell past character 160 the test failed and the verse was classed UNPROVEN with the reason "named there but not quoted with its reference". Luke 1:35 is 221 characters in the KJV: in run 42528 the defender's round DR1 quotes Luke 1:35 whole five times and all five hits failed, and the judges were told three times "Luke 1:35 (PROVEN IN [DR1]: the verse is named there but not quoted with its reference)". Change, one expression in each of four copies (D4 Build, Panel Build, Build Independent Verdict, Shared Library): the window runs from the reference to the end of that line. The quotation test itself is unchanged. Expected effect: a verse whose quotation is whole on its line reads PROVEN BY REFERENCE, in the Oracle's list of unproven presses and in the judges' press ledger. Not changed: ruling 398, the cap, the WALL-2024 floor, a model setting, reasoning. (plan rev 0, ask651/w4/plan651.md md5 a6d624d4)$t$,
  'in part',
  $t$One build, one card and one write carry ASK 651 and ASK 652 together: target 1aa15175, written by W4 on the operator's press "Write it" at 09:09 CST 2026-11-25 on W4's card (Wall 12127; audit 42304), engine 7f4e5503 to 50ade174 (426 nodes; the child aad0ad9c unchanged), build graded PASS by W1 (Wall 12108: W1 ran b651 and b652 on its own live copy and the result equals the target in every node parameter and in the connections; only D4 Build, Panel Build, Build Independent Verdict and Shared Library change) and read back PASS by W1 (Wall 12129). IN PART, because no run has been made since the write. For ASK 651: plan rev 0 PASS WITH N1 (Wall 12101: the 160-character slice occurs once in each of the four nodes in live 7f4e5503 and the defect is confirmed; running the window to the end of the line changes nothing else, because the test already stops at a newline). N1 (in the Shared Library JSON-line copy the newline must be written escaped) is met in the build (Wall 12108). Offline replay (W4, Wall 12102, 12105): with 651 and 652 together the Oracle's list of unproven presses for 42528 holds only "premise 4: Luke 1:34", a WALL-2024 floor item held for the operator by the coordinator, and for 42373 "none". W4 corrected its own Wall 12100: the 8-character values there were sha256 prefixes; the plan of record by md5 is a6d624d4 (Wall 12102). NOT CHECKED by W1: W4's replay figures; W4's 18-of-18 match of the "before" replay to the live Panel Build output; the Library Check hashes; audit 42304. Open: two clean live runs.$t$,
  '12100, 12101, 12102, 12105, 12108, 12127, 12129, 12139, 12145, 12152',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$W4's write card (cmsg_017ZQamDMHrS6fqMHnQDVo58F12ck7RxDR9wiG7wni57j5, "Write ASK 651 + 652 to the live engine?"): he pressed "Write it" at 09:09 CST 2026-11-25 (one card and one write for ASK 651 and ASK 652). Card text, press and time are from W4's facts file; W3 did not read the card or the press. There was no build card: the build was offline files only, and the card came after the build grade.$t$::text),
  $j${"answer": "Write it", "question": "Write ASK 651 + 652 to the live engine?", "options": {"Write it": "Stops the engine telling judges proven verses are \"not a witness\" and telling the Oracle proven presses cost nothing. Reverts with one file.", "Hold": "Next run keeps the false UNPROVEN labels and the false costless list (25 such labels were in the 42528 judge text)."}, "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58F12ck7RxDR9wiG7wni57j5", "press_time": "09:09 CST 2026-11-25", "message_above_the_card": "cmsg_017ZQamDMHrS6fqMHnQDVo58YEDWGeV3txREtJW5gMFKEk", "source": "W4's facts file aar/w3/cards_641_to_652_from_w4.md; W3 did not read the card or the press. One card and one write cover ASK 651 and ASK 652."}$j$::jsonb,
  'W4',
  $j${"md5": "a6d624d4cb9d42e2ca05630da7a4c2ce", "path": "ask651/w4/plan651.md", "note": "plan rev 0, graded PASS WITH N1 by W1 (Wall 12101); N1 met in the build (Wall 12108).", "source": "md5sum by W3; Wall 12101, 12103"}$j$::jsonb,
  $j$[{"path": "ask652/w4/b1/b651.cjs", "md5": "48a0048214be19d6b5ab2b000aeae50a", "what": "build script, ASK 651"}, {"path": "ask652/w4/b1/b652.cjs", "md5": "ce310e99761c0b10d566585f9cb672dd", "what": "build script, ASK 652"}, {"path": "ask652/w4/b1/tg/target_engine_651_652.json", "md5": "1aa1517517fc227ef4e8d9cd75d05917", "what": "target engine, both together (written)"}, {"path": "ask652/w4/b1/tg/target_engine_651.json", "md5": "70329a64d0a33f9f7ef7d67ca12c34b4", "what": "intermediate target, 651 alone (not graded alone, not written)"}, {"path": "ask652/w4/b1/t651_652.cjs", "md5": "9660e42444963769796347d92c37d760", "what": "test"}, {"path": "ask652/w4/b1/out_t651_652.txt", "md5": "9352cdbc844bc02a1913e5e467c7c82e", "what": "test output"}, {"path": "ask652/w4/b1/ledger652.cjs", "md5": "cac55627d06cb32aae9467f1133aba6d", "what": "ledger replay script"}, {"path": "ask652/w4/b1/out_r42528_PanelBuild_before.txt", "md5": "693c2c1b4a1aa1c4b3c336f9a951a54a", "what": "42528 judge ledger before (Build Independent Verdict gives the same text)"}, {"path": "ask652/w4/b1/out_r42528_PanelBuild_after.txt", "md5": "98f546c6ee97fd0b3ce5235254e7edc7", "what": "42528 judge ledger after"}, {"path": "ask652/w4/b1/build_notes.md", "md5": "561bb72aecff0cf5c0df733b8c1c5c91", "what": "build notes"}, {"path": "ask652/w4/write/fetchback_eng_651_652.json", "md5": "4bf159e462b3843fe283c7255ac8f6d7", "what": "fetch-back after the write (md5 from W4's facts file)"}, {"path": "ask652/w4/write/write651_652.sh", "md5": "5e627cc5ca2db076457e88160f6e337b", "what": "write script (md5 from W4's facts file)"}]$j$::jsonb,
  $j${"engine": "ask652/w4/write/revert_eng_651_652.json, md5 60a8ddf02c11f8b0cf506816b2a71f75 (restores 7f4e5503; md5 from W4's facts file); one file reverts ASK 651 and ASK 652 together", "child": "not written; nothing to revert", "database": "not written; nothing to revert", "rehearsed": "not stated in the posts W3 read", "source": "Wall 12127; W4's facts file"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH N1 (plan rev 0)", "wall_id": 12101, "md5_graded": "a6d624d4", "verdict_norm": "PASS", "source": "Wall 12101"}, {"seat": "W1", "verdict": "PASS (build b1, ASK 651 and 652 together)", "wall_id": 12108, "md5_graded": "1aa15175", "verdict_norm": "PASS", "source": "Wall 12108"}, {"seat": "W1", "verdict": "PASS (written target check with the full md5, made after the write: equal to live 50ade174, 426 nodes, 0 differences, connections equal)", "wall_id": 12152, "md5_graded": "1aa1517517fc227ef4e8d9cd75d05917", "verdict_norm": "PASS", "source": "Wall 12152, item 3"}]$j$::jsonb,
  ARRAY['1aa1517517fc227ef4e8d9cd75d05917'], '[42304]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN, nodes D4 Build, Panel Build, Build Independent Verdict and Shared Library (LIB line 36)", "before": "version 7f4e5503; PRS refCheck reads 160 characters after a reference; the premise reader in D4 Build, Panel Build and Build Independent Verdict treats every reference in a PRESSED WITH block as a press", "after": "version 50ade174-e08d-48a2-95de-1fd4bcbebcfd, 426 nodes; refCheck reads to the end of the line (four copies, tagged ASK 651); the premise reader passes over a reference that is neither a pressed verse nor a press past the cap of PRS.premise (three copies, tagged ASK 652); 29 MAP lengths re-measured; LIB 78f56d1449dc8e96, map b5974b30d48fe432"}]$j$::jsonb,
  $j$[{"name": "t651_652.cjs on the build", "result": "ALL PASS (28): each of the four refCheck copies gives Luke 1:35 PROVEN BY REFERENCE on 42528 DR1; no PROVEN BY REFERENCE verdict of 42528 or 42373 changes; a quotation with no closing mark on its line still fails; a verse named but not quoted still reads \"not quoted\"; the LIB source writes the newline escaped (test 6); 10 real presses give 8 counted and \"over the cap\" names the two past it, not an [L3] verse (test 28); the PRSP-null case", "source": "Wall 12105; run by W1 on its own rebuild, Wall 12108, and on live, Wall 12129"}, {"name": "Judge ledger replay, 42528 and 42373, before and after", "result": "42528: Luke 1:35 becomes PROVEN BY REFERENCE in defender premises 2, 3 and 4; 25 layer verses of the Oracle's presses lose the label \"UNPROVEN, not a witness\"; Job 14:1 and Acts 13:33 are counted as presses; both WALL-2024 floor items stay (Luke 1:34 in premise 4, 2 Samuel 7:12). 42373: the challenger's presses Luke 1:32 and Hebrews 7:10 are counted. Panel Build and Build Independent Verdict give the same text.", "source": "Wall 12105; the 42528 ledger read by W1, Wall 12108"}, {"name": "Standing set with child aad0ad9c", "result": "31 PASS, 0 FAIL on the target (W4, W1), before and after the write (W4, Wall 12127) and on live (W1, Wall 12129); pair Library Check PASSES; one-copy check PASS", "source": "Wall 12105, 12108, 12127, 12129"}, {"name": "NOT RUN", "result": "any live call", "source": "Wall 12127"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "PASS (live 50ade174, saved and active; equal to W1's own rebuild, target 1aa15175, in every node parameter and in the connections; only the four planned nodes changed and no node settings differ; standing 31 PASS 0 FAIL on live; W4's tests 28 of 28 on live). NOT CHECKED: audit 42304.", "wall_id": 12129, "source": "Wall 12129 (commit e0a5cb61)"}]$j$::jsonb,
  $j${"case": "NO RUN YET.", "runs": [], "mark_for_the_next_run": "in the press ledger a verse whose quotation in the named round is whole on its line reads PROVEN BY REFERENCE (in 42528 terms: Luke 1:35 where the [DR1] quotation is whole).", "not_shown": "the longer window on a live run.", "source": "Wall 12127"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "WRITTEN: part 09.7 version 334 (md5 aad0512ad7d348f1d3e7cb57cfda4c52, 40,564 characters, log row 354), one entry for ASK 651 and ASK 652, on the operator's press \"Write it\" at 09:25 CST 2026-11-25 on W3's card (cmsg_017ZQamDMHrS6fqMHnQDVo58EXf4nVUXyvi6Dm3sMW7rJj); audit 42323; pairs draft 2 graded PASS by W1 (Wall 12139); read back PASS by W1 (Wall 12152, item 2)."}$j$::jsonb,
  'read back', $j$[12100, 12101, 12102, 12105, 12108, 12127, 12129, 12139, 12145, 12152]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W4'], $j$[{"seat": "W4", "what": "planned, built (build b1, with ASK 652) and wrote ASK 651 on the operator's card", "wall_id": 12127}]$j$::jsonb, current_setting('truth.session_id') FROM s;
SELECT * FROM ask_aar_snapshots_check() WHERE row_id = (SELECT max(id) FROM ask_aar_snapshots);
SELECT * FROM ask_aar_grades_check() WHERE snapshot_id = (SELECT max(id) FROM ask_aar_snapshots);
COMMIT;
